    AcceptNetworkFirewallTransitGatewayAttachmentRequest.add_member(:transit_gateway_attachment_id, Smithy::Schema::Shapes::ShapeRef.new(shape: TransitGatewayAttachmentId, location_name: 'TransitGatewayAttachmentId', traits: {"smithy.api#documentation" => "<p>Required. The unique identifier of the transit gateway attachment to accept. This ID is returned in the response when creating a transit gateway-attached firewall.</p>", "smithy.api#required" => {}}))
