    AcceptNetworkFirewallTransitGatewayAttachmentResponse.add_member(:transit_gateway_attachment_id, Smithy::Schema::Shapes::ShapeRef.new(shape: TransitGatewayAttachmentId, location_name: 'TransitGatewayAttachmentId', traits: {"smithy.api#documentation" => "<p>The unique identifier of the transit gateway attachment that was accepted.</p>", "smithy.api#required" => {}}))
    AcceptNetworkFirewallTransitGatewayAttachmentResponse.add_member(:transit_gateway_attachment_status, Smithy::Schema::Shapes::ShapeRef.new(shape: TransitGatewayAttachmentStatus, location_name: 'TransitGatewayAttachmentStatus', traits: {"smithy.api#documentation" => "<p>The current status of the transit gateway attachment. Valid values are:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>CREATING</code> - The attachment is being created</p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETING</code> - The attachment is being deleted</p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETED</code> - The attachment has been deleted</p>\n            </li>\n            <li>\n               <p>\n                  <code>FAILED</code> - The attachment creation has failed and cannot be recovered</p>\n            </li>\n            <li>\n               <p>\n                  <code>ERROR</code> - The attachment is in an error state that might be recoverable</p>\n            </li>\n            <li>\n               <p>\n                  <code>READY</code> - The attachment is active and processing traffic</p>\n            </li>\n            <li>\n               <p>\n                  <code>PENDING_ACCEPTANCE</code> - The attachment is waiting to be accepted</p>\n            </li>\n            <li>\n               <p>\n                  <code>REJECTING</code> - The attachment is in the process of being rejected</p>\n            </li>\n            <li>\n               <p>\n                  <code>REJECTED</code> - The attachment has been rejected</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
