    CheckCertificateRevocationStatusActions.add_member(:revoked_status_action, Smithy::Schema::Shapes::ShapeRef.new(shape: RevocationCheckAction, location_name: 'RevokedStatusAction', traits: {"smithy.api#documentation" => "<p>Configures how Network Firewall processes traffic when it determines that the certificate presented by the server in the SSL/TLS connection has a revoked status.</p>\n         <ul>\n            <li>\n               <p>\n                  <b>PASS</b> - Allow the connection to continue, and pass subsequent packets to the stateful engine for inspection.</p>\n            </li>\n            <li>\n               <p>\n                  <b>DROP</b> - Network Firewall closes the connection and drops subsequent packets for that connection.</p>\n            </li>\n            <li>\n               <p>\n                  <b>REJECT</b> - Network Firewall sends a TCP reject packet back to your client. The service closes the connection and drops subsequent packets for that connection. <code>REJECT</code> is available only for TCP traffic.</p>\n            </li>\n         </ul>"}))
    CheckCertificateRevocationStatusActions.add_member(:unknown_status_action, Smithy::Schema::Shapes::ShapeRef.new(shape: RevocationCheckAction, location_name: 'UnknownStatusAction', traits: {"smithy.api#documentation" => "<p>Configures how Network Firewall processes traffic when it determines that the certificate presented by the server in the SSL/TLS connection has an unknown status, or a status that cannot be determined for any other reason, including when the service is unable to connect to the OCSP and CRL endpoints for the certificate.</p>\n         <ul>\n            <li>\n               <p>\n                  <b>PASS</b> - Allow the connection to continue, and pass subsequent packets to the stateful engine for inspection.</p>\n            </li>\n            <li>\n               <p>\n                  <b>DROP</b> - Network Firewall closes the connection and drops subsequent packets for that connection.</p>\n            </li>\n            <li>\n               <p>\n                  <b>REJECT</b> - Network Firewall sends a TCP reject packet back to your client. The service closes the connection and drops subsequent packets for that connection. <code>REJECT</code> is available only for TCP traffic.</p>\n            </li>\n         </ul>"}))
    CheckCertificateRevocationStatusActions.type = Types::CheckCertificateRevocationStatusActions
