    CreateFirewallRequest.add_member(:subnet_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetMappings, location_name: 'SubnetMappings', traits: {"smithy.api#documentation" => "<p>The public subnets to use for your Network Firewall firewalls. Each subnet must belong to a\n         different Availability Zone in the VPC. Network Firewall creates a firewall endpoint in each\n         subnet. </p>"}))
    CreateFirewallRequest.add_member(:delete_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DeleteProtection', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>A flag indicating whether it is possible to delete the firewall. A setting of <code>TRUE</code> indicates\n         that the firewall is protected against deletion. Use this setting to protect against\n         accidentally deleting a firewall that is in use. When you create a firewall, the operation initializes this flag to <code>TRUE</code>.</p>"}))
    CreateFirewallRequest.add_member(:subnet_change_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'SubnetChangeProtection', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>A setting indicating whether the firewall is protected against changes to the subnet associations.\n         Use this setting to protect against\n         accidentally modifying the subnet associations for a firewall that is in use. When you create a firewall, the operation initializes this setting to <code>TRUE</code>.</p>"}))
    CreateFirewallRequest.add_member(:firewall_policy_change_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'FirewallPolicyChangeProtection', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>A setting indicating whether the firewall is protected against a change to the firewall policy association.\n         Use this setting to protect against\n         accidentally modifying the firewall policy for a firewall that is in use. When you create a firewall, the operation initializes this setting to <code>TRUE</code>.</p>"}))
