    CreateFirewallRequest.add_member(:encryption_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionConfiguration, location_name: 'EncryptionConfiguration', traits: {"smithy.api#documentation" => "<p>A complex type that contains settings for encryption of your firewall resources.</p>"}))
    CreateFirewallRequest.add_member(:enabled_analysis_types, Smithy::Schema::Shapes::ShapeRef.new(shape: EnabledAnalysisTypes, location_name: 'EnabledAnalysisTypes', traits: {"smithy.api#documentation" => "<p>An optional setting indicating the specific traffic analysis types to enable on the firewall. </p>"}))
    CreateFirewallRequest.add_member(:transit_gateway_id, Smithy::Schema::Shapes::ShapeRef.new(shape: TransitGatewayId, location_name: 'TransitGatewayId', traits: {"smithy.api#documentation" => "<p>Required when creating a transit gateway-attached firewall. The unique identifier of the transit gateway to attach to this firewall. You can provide either a transit gateway from your account or one that has been shared with you through Resource Access Manager.</p>\n         <important>\n            <p>After creating the firewall, you cannot change the transit gateway association. To use a different transit gateway, you must create a new firewall.</p>\n         </important>\n         <p>For information about creating firewalls, see <a>CreateFirewall</a>. For specific guidance about transit gateway-attached firewalls, see <a href=\"https://docs.aws.amazon.com/network-firewall/latest/developerguide/tgw-firewall-considerations.html\">Considerations for transit gateway-attached firewalls</a> in the <i>Network Firewall Developer Guide</i>.</p>"}))
    CreateFirewallRequest.add_member(:availability_zone_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZoneMappings, location_name: 'AvailabilityZoneMappings', traits: {"smithy.api#documentation" => "<p>Required. The Availability Zones where you want to create firewall endpoints for a transit gateway-attached firewall. You must specify at least one Availability Zone. Consider enabling the firewall in every Availability Zone where you have workloads to maintain Availability Zone independence.</p>\n         <p>You can modify Availability Zones later using <a>AssociateAvailabilityZones</a> or <a>DisassociateAvailabilityZones</a>, but this may briefly disrupt traffic. The <code>AvailabilityZoneChangeProtection</code> setting controls whether you can make these modifications.</p>"}))
    CreateFirewallRequest.add_member(:availability_zone_change_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AvailabilityZoneChangeProtection', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Optional. A setting indicating whether the firewall is protected against changes to its Availability Zone configuration. When set to <code>TRUE</code>, you cannot add or remove Availability Zones without first disabling this protection using <a>UpdateAvailabilityZoneChangeProtection</a>.</p>\n         <p>Default value: <code>FALSE</code>\n         </p>"}))
    CreateFirewallRequest.type = Types::CreateFirewallRequest
    CreateFirewallResponse.add_member(:firewall, Smithy::Schema::Shapes::ShapeRef.new(shape: Firewall, location_name: 'Firewall', traits: {"smithy.api#documentation" => "<p>The configuration settings for the firewall. These settings include the firewall policy and the subnets in your VPC to use for the firewall endpoints. </p>"}))
    CreateFirewallResponse.add_member(:firewall_status, Smithy::Schema::Shapes::ShapeRef.new(shape: FirewallStatus, location_name: 'FirewallStatus', traits: {"smithy.api#documentation" => "<p>Detailed information about the current status of a <a>Firewall</a>. You can retrieve this for a firewall by calling <a>DescribeFirewall</a> and providing the firewall name and ARN.</p>\n         <p>The firewall status indicates a combined status. It indicates whether all subnets are up-to-date with the latest firewall configurations, which is based on the sync states config values, and also whether all subnets have their endpoints fully enabled, based on their sync states attachment values. </p>"}))
