    CreateRuleGroupRequest.add_member(:rule_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceName, location_name: 'RuleGroupName', traits: {"smithy.api#documentation" => "<p>The descriptive name of the rule group. You can't change the name of a rule group after you create it.</p>", "smithy.api#required" => {}}))
    CreateRuleGroupRequest.add_member(:rule_group, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleGroup, location_name: 'RuleGroup', traits: {"smithy.api#documentation" => "<p>An object that defines the rule group rules. </p>\n         <note>\n            <p>You must provide either this rule group setting or a <code>Rules</code> setting, but not both. </p>\n         </note>"}))
    CreateRuleGroupRequest.add_member(:rules, Smithy::Schema::Shapes::ShapeRef.new(shape: RulesString, location_name: 'Rules', traits: {"smithy.api#documentation" => "<p>A string containing stateful rule group rules specifications in Suricata flat format, with one rule\nper line. Use this to import your existing Suricata compatible rule groups. </p>\n         <note>\n            <p>You must provide either this rules setting or a populated <code>RuleGroup</code> setting, but not both. </p>\n         </note>\n         <p>You can provide your rule group specification in Suricata flat format through this setting when you create or update your rule group. The call\nresponse returns a <a>RuleGroup</a> object that Network Firewall has populated from your string. </p>"}))
    CreateRuleGroupRequest.add_member(:type, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleGroupType, location_name: 'Type', traits: {"smithy.api#documentation" => "<p>Indicates whether the rule group is stateless or stateful. If the rule group is stateless, it contains\nstateless rules. If it is stateful, it contains stateful rules. </p>", "smithy.api#required" => {}}))
    CreateRuleGroupRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: Description, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description of the rule group. </p>"}))
    CreateRuleGroupRequest.add_member(:capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleCapacity, location_name: 'Capacity', traits: {"smithy.api#documentation" => "<p>The maximum operating resources that this rule group can use. Rule group capacity is fixed at creation.\n      When you update a rule group, you are limited to this capacity. When you reference a rule group\n      from a firewall policy, Network Firewall reserves this capacity for the rule group. </p>\n         <p>You can retrieve the capacity that would be required for a rule group before you create the rule group by calling\n      <a>CreateRuleGroup</a> with <code>DryRun</code> set to <code>TRUE</code>. </p>\n         <note>\n            <p>You can't change or exceed this capacity when you update the rule group, so leave\n            room for your rule group to grow. </p>\n         </note>\n         <p>\n            <b>Capacity for a stateless rule group</b>\n         </p>\n         <p>For a stateless rule group, the capacity required is the sum of the capacity\n         requirements of the individual rules that you expect to have in the rule group. </p>\n         <p>To calculate the capacity requirement of a single rule, multiply the capacity\n         requirement values of each of the rule's match settings:</p>\n         <ul>\n            <li>\n               <p>A match setting with no criteria specified has a value of 1. </p>\n            </li>\n            <li>\n               <p>A match setting with <code>Any</code> specified has a value of 1. </p>\n            </li>\n            <li>\n               <p>All other match settings have a value equal to the number of elements provided in\n               the setting. For example, a protocol setting [\"UDP\"] and a source setting\n               [\"10.0.0.0/24\"] each have a value of 1. A protocol setting [\"UDP\",\"TCP\"] has a value\n               of 2. A source setting [\"10.0.0.0/24\",\"10.0.0.1/24\",\"10.0.0.2/24\"] has a value of 3.\n            </p>\n            </li>\n         </ul>\n         <p>A rule with no criteria specified in any of its match settings has a capacity\n         requirement of 1. A rule with protocol setting [\"UDP\",\"TCP\"], source setting\n         [\"10.0.0.0/24\",\"10.0.0.1/24\",\"10.0.0.2/24\"], and a single specification or no specification\n         for each of the other match settings has a capacity requirement of 6. </p>\n         <p>\n            <b>Capacity for a stateful rule group</b>\n         </p>\n         <p>For a stateful rule group, the minimum capacity required is the number of individual rules that\n         you expect to have in the rule group. </p>", "smithy.api#required" => {}}))
    CreateRuleGroupRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The key:value pairs to associate with the resource.</p>"}))
    CreateRuleGroupRequest.add_member(:dry_run, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DryRun', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Indicates whether you want Network Firewall to just check the validity of the request, rather than run the request. </p>\n         <p>If set to <code>TRUE</code>, Network Firewall checks whether the request can run successfully,\n         but doesn't actually make the requested changes. The call returns the value that the request would return if you ran it with\n         dry run set to <code>FALSE</code>, but doesn't make additions or changes to your resources. This option allows you to make sure that you have\n         the required permissions to run the request and that your request parameters are valid. </p>\n         <p>If set to <code>FALSE</code>, Network Firewall makes the requested changes to your resources. </p>"}))
    CreateRuleGroupRequest.add_member(:encryption_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionConfiguration, location_name: 'EncryptionConfiguration', traits: {"smithy.api#documentation" => "<p>A complex type that contains settings for encryption of your rule group resources.</p>"}))
    CreateRuleGroupRequest.add_member(:source_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: SourceMetadata, location_name: 'SourceMetadata', traits: {"smithy.api#documentation" => "<p>A complex type that contains metadata about the rule group that your own rule group is copied from. You can use the metadata to keep track of updates made to the originating rule group.</p>"}))
    CreateRuleGroupRequest.add_member(:analyze_rule_group, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AnalyzeRuleGroup', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Indicates whether you want Network Firewall to analyze the stateless rules in the rule group for rule behavior such as asymmetric routing. If set to <code>TRUE</code>, Network Firewall runs the analysis and then creates the rule group for you. To run the stateless rule group analyzer without creating the rule group, set <code>DryRun</code> to <code>TRUE</code>.</p>"}))
