    Firewall.add_member(:subnet_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: SubnetMappings, location_name: 'SubnetMappings', traits: {"smithy.api#documentation" => "<p>The primary public subnets that Network Firewall is using for the firewall. Network Firewall creates a firewall endpoint in each subnet. Create a subnet mapping for each Availability Zone where you want to use the firewall.</p>\n         <p>These subnets are all defined for a single, primary VPC, and each must belong to a different Availability Zone. Each of these subnets establishes the availability of the firewall in its Availability Zone. </p>\n         <p>In addition to these subnets, you can define other endpoints for the firewall in <code>VpcEndpointAssociation</code> resources. You can define these additional endpoints for any VPC, and for any of the Availability Zones where the firewall resource already has a subnet mapping. VPC endpoint associations give you the ability to protect multiple VPCs using a single firewall, and to define multiple firewall endpoints for a VPC in a single Availability Zone. </p>", "smithy.api#required" => {}}))
    Firewall.add_member(:delete_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'DeleteProtection', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>A flag indicating whether it is possible to delete the firewall. A setting of <code>TRUE</code> indicates\n         that the firewall is protected against deletion. Use this setting to protect against\n         accidentally deleting a firewall that is in use. When you create a firewall, the operation initializes this flag to <code>TRUE</code>.</p>"}))
