    FirewallPolicy.add_member(:stateful_rule_group_references, Smithy::Schema::Shapes::ShapeRef.new(shape: StatefulRuleGroupReferences, location_name: 'StatefulRuleGroupReferences', traits: {"smithy.api#documentation" => "<p>References to the stateful rule groups that are used in the policy. These define the\n         inspection criteria in stateful rules. </p>"}))
    FirewallPolicy.add_member(:stateful_default_actions, Smithy::Schema::Shapes::ShapeRef.new(shape: StatefulActions, location_name: 'StatefulDefaultActions', traits: {"smithy.api#documentation" => "<p>The default actions to take on a packet that doesn't match any stateful rules. The stateful default action is optional,\n         and is only valid when using the strict rule order.</p>\n         <p>Valid values of the stateful default action:</p>\n         <ul>\n            <li>\n               <p>aws:drop_strict</p>\n            </li>\n            <li>\n               <p>aws:drop_established</p>\n            </li>\n            <li>\n               <p>aws:alert_strict</p>\n            </li>\n            <li>\n               <p>aws:alert_established</p>\n            </li>\n         </ul>\n         <p>For more information, see\n         <a href=\"https://docs.aws.amazon.com/network-firewall/latest/developerguide/suricata-rule-evaluation-order.html#suricata-strict-rule-evaluation-order.html\">Strict evaluation order</a> in the <i>Network Firewall Developer Guide</i>.\n      </p>"}))
