    StatefulAction.add_member(:alert, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ALERT', traits: {"smithy.api#enumValue" => "ALERT"}))
