    StatefulRuleGroupOverride.add_member(:action, Smithy::Schema::Shapes::ShapeRef.new(shape: OverrideAction, location_name: 'Action', traits: {"smithy.api#documentation" => "<p>The action that changes the rule group from <code>DROP</code> to <code>ALERT</code>. This only applies to\n      managed rule groups.</p>"}))
