    StatefulRuleGroupReference.add_member(:resource_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceArn, location_name: 'ResourceArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the stateful rule group.</p>", "smithy.api#required" => {}}))
    StatefulRuleGroupReference.add_member(:priority, Smithy::Schema::Shapes::ShapeRef.new(shape: Priority, location_name: 'Priority', traits: {"smithy.api#documentation" => "<p>An integer setting that indicates the order in which to run the stateful rule groups in\n      a single <a>FirewallPolicy</a>. This setting only applies to firewall policies\n      that specify the <code>STRICT_ORDER</code> rule order in the stateful engine options settings.</p>\n         <p>Network Firewall evalutes each stateful rule group\n         against a packet starting with the group that has the lowest priority setting. You must ensure\n         that the priority settings are unique within each policy.</p>\n         <p>You can change the priority settings of your rule groups at any time. To make it easier to\n         insert rule groups later, number them so there's a wide range in between, for example use 100,\n         200, and so on. </p>"}))
    StatefulRuleGroupReference.add_member(:override, Smithy::Schema::Shapes::ShapeRef.new(shape: StatefulRuleGroupOverride, location_name: 'Override', traits: {"smithy.api#documentation" => "<p>The action that allows the policy owner to override the behavior of the rule group within a policy.</p>"}))
    StatefulRuleGroupReference.add_member(:deep_threat_inspection, Smithy::Schema::Shapes::ShapeRef.new(shape: DeepThreatInspection, location_name: 'DeepThreatInspection', traits: {"smithy.api#documentation" => "<p>Network Firewall plans to augment the active threat defense managed rule group with an additional deep threat inspection capability. When this capability is released, Amazon Web Services will analyze service logs of network traffic processed by these rule groups to identify threat indicators across customers. \n         Amazon Web Services will use these threat indicators to improve the active threat defense managed rule groups and protect the security of Amazon Web Services customers and services.</p>\n         <note>\n            <p>Customers can opt-out of deep threat inspection at any time through the Network Firewall console or API. When customers opt out, Network Firewall  will not use the network traffic processed by those customers' active threat defense rule groups for rule group improvement.</p>\n         </note>"}))
    StatefulRuleGroupReference.type = Types::StatefulRuleGroupReference
    StatefulRuleGroupReferences.member = Smithy::Schema::Shapes::ShapeRef.new(shape: StatefulRuleGroupReference)
    StatefulRuleOptions.add_member(:rule_order, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleOrder, location_name: 'RuleOrder', traits: {"smithy.api#documentation" => "<p>Indicates how to manage the order of the rule evaluation for the rule group. <code>DEFAULT_ACTION_ORDER</code> is\n             the default behavior. Stateful rules are provided to the rule engine as Suricata compatible strings, and Suricata evaluates them\n             based on certain settings. For more information, see\n         <a href=\"https://docs.aws.amazon.com/network-firewall/latest/developerguide/suricata-rule-evaluation-order.html\">Evaluation order for stateful rules</a> in the <i>Network Firewall Developer Guide</i>.\n      </p>"}))
