    TransitGatewayAttachmentSyncState.add_member(:transit_gateway_attachment_status, Smithy::Schema::Shapes::ShapeRef.new(shape: TransitGatewayAttachmentStatus, location_name: 'TransitGatewayAttachmentStatus', traits: {"smithy.api#documentation" => "<p>The current status of the transit gateway attachment.</p>\n         <p>Valid values are:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>CREATING</code> - The attachment is being created</p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETING</code> - The attachment is being deleted</p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETED</code> - The attachment has been deleted</p>\n            </li>\n            <li>\n               <p>\n                  <code>FAILED</code> - The attachment creation has failed and cannot be recovered</p>\n            </li>\n            <li>\n               <p>\n                  <code>ERROR</code> - The attachment is in an error state that might be recoverable</p>\n            </li>\n            <li>\n               <p>\n                  <code>READY</code> - The attachment is active and processing traffic</p>\n            </li>\n            <li>\n               <p>\n                  <code>PENDING_ACCEPTANCE</code> - The attachment is waiting to be accepted</p>\n            </li>\n            <li>\n               <p>\n                  <code>REJECTING</code> - The attachment is in the process of being rejected</p>\n            </li>\n            <li>\n               <p>\n                  <code>REJECTED</code> - The attachment has been rejected</p>\n            </li>\n         </ul>"}))
    TransitGatewayAttachmentSyncState.add_member(:status_message, Smithy::Schema::Shapes::ShapeRef.new(shape: TransitGatewayAttachmentSyncStateMessage, location_name: 'StatusMessage', traits: {"smithy.api#documentation" => "<p>A message providing additional information about the current status, particularly useful when the transit gateway attachment is in a non-<code>READY</code> state.</p>\n         <p>Valid values are:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>CREATING</code> - The attachment is being created</p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETING</code> - The attachment is being deleted</p>\n            </li>\n            <li>\n               <p>\n                  <code>DELETED</code> - The attachment has been deleted</p>\n            </li>\n            <li>\n               <p>\n                  <code>FAILED</code> - The attachment creation has failed and cannot be recovered</p>\n            </li>\n            <li>\n               <p>\n                  <code>ERROR</code> - The attachment is in an error state that might be recoverable</p>\n            </li>\n            <li>\n               <p>\n                  <code>READY</code> - The attachment is active and processing traffic</p>\n            </li>\n            <li>\n               <p>\n                  <code>PENDING_ACCEPTANCE</code> - The attachment is waiting to be accepted</p>\n            </li>\n            <li>\n               <p>\n                  <code>REJECTING</code> - The attachment is in the process of being rejected</p>\n            </li>\n            <li>\n               <p>\n                  <code>REJECTED</code> - The attachment has been rejected</p>\n            </li>\n         </ul>\n         <p>For information about troubleshooting endpoint failures, see <a href=\"https://docs.aws.amazon.com/network-firewall/latest/developerguide/firewall-troubleshooting-endpoint-failures.html\">Troubleshoo